INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES
('9813f2de-ac3f-494b-ae9b-3f65e3d676cc', '21feff02-016d-46e2-bb9d-c27495133b1b', '54. óra: Szerkesztések II.', 'Egyszerű szerkesztési feladatok: háromszög szerkesztése oldalaiból (SSSZ), háromszög-egyenlőtlenség.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "55553fd3-363d-459e-ae56-593c3bd705fd", "text": "Mi a háromszög-egyenlőtlenség szabálya?", "type": "multiple-choice", "options": [{"id": "5c68e43f-963b-49f8-b519-1735905531c4", "text": "A háromszög bármely két oldalának összege nagyobb a harmadik oldalnál (a + b > c)", "isCorrect": true}, {"id": "5b0e5392-04be-40d8-9a34-f85d6b1c33d9", "text": "A három oldal összege 180", "isCorrect": false}, {"id": "94f56ffe-2365-4454-be47-13b1c4f35ca3", "text": "A két rövidebb oldal összege kisebb a harmadiknál", "isCorrect": false}, {"id": "90bcc1e7-643d-445d-8b19-73732b6a9be6", "text": "Minden oldal egyenlő", "isCorrect": false}], "timeLimit": 15}, {"id": "bdd10ddb-4a46-4003-9b5d-1e0ff5797eba", "text": "Szerkeszthető-e háromszög a 3 cm, 4 cm, 8 cm oldalakkal? (3+4 = 7 < 8)", "type": "true-false", "options": [{"id": "b94fe913-f10b-4f3d-adf4-f018c007146b", "text": "Igaz", "isCorrect": false}, {"id": "d6bedf82-0f7b-4cb6-b5d7-ce6e03e77e0c", "text": "Hamis (nem teljesül a háromszög-egyenlőtlenség)", "isCorrect": true}], "timeLimit": 15}, {"id": "99d111ba-d2f7-4f3e-b3ad-b98c93c8d6aa", "text": "Szerkeszthető-e háromszög 5 cm, 6 cm, 7 cm oldalakkal?", "type": "true-false", "options": [{"id": "27282e93-2908-47c1-9961-798e6b9e8546", "text": "Igaz (5+6 > 7)", "isCorrect": true}, {"id": "220c35c0-e026-4123-aef6-16719c3f8b37", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "15d256cc-ef1a-4963-8cff-4a5eda306994", "text": "Hány adatra van szükség legalább egy háromszög egyértelmű megszerkesztéséhez?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "0be6210e-bdb0-4bb0-8f3d-1eceab6c602e", "text": "A háromszög szerkesztésének lépései: Vázlat -> Adatok -> Szerkesztés -> Ellenőrzés.", "type": "true-false", "options": [{"id": "e97edfb0-08cd-4e72-b4dd-5f7a437ee4c4", "text": "Igaz", "isCorrect": true}, {"id": "8a548cd0-846b-4b48-89e9-9105a468f4e8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "709e8a18-238b-4bb0-96b2-40afb31bc9db", "text": "Szerkeszthető-e háromszög 2 cm, 3 cm, 5 cm oldalakkal? (2+3 = 5)", "type": "true-false", "options": [{"id": "439752bc-2c6d-4364-b3de-618bd4a244b9", "text": "Igaz", "isCorrect": false}, {"id": "ae25f181-5d45-4770-a2bf-9ea6664b5722", "text": "Hamis (kell hogy > legyen, nem =)", "isCorrect": true}], "timeLimit": 15}, {"id": "186f13be-b3d0-4089-8734-d653803456f2", "text": "Az egyenlő oldalú háromszög minden oldala egyenlő hosszú.", "type": "true-false", "options": [{"id": "7f45144a-9670-4dfe-8733-11875bdbbbcd", "text": "Igaz", "isCorrect": true}, {"id": "2945345f-7b39-4670-8960-d6e6b08b1545", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('5408f11f-904b-45ac-973e-1d4eb5caeb9c', '21feff02-016d-46e2-bb9d-c27495133b1b', '55. óra: Számonkérés', 'Számonkérés a síkbeli alakzatokból és alapszerkesztésekből (10 kérdés).', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "54b32f1f-8978-4973-a3de-dc50d3fb7d59", "text": "1. Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "071e13eb-2bcf-4735-9024-3a2ff02ba2e5", "text": "2. Mennyi a négyszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "3802489c-7764-4268-bf14-10e7246d389f", "text": "3. Szerkeszthető-e háromszög 4 cm, 5 cm, 10 cm oldalakkal?", "type": "true-false", "options": [{"id": "c282490f-8270-4f28-8163-8a8b3d40f5f5", "text": "Igaz", "isCorrect": false}, {"id": "7b6a73b6-25ab-4f98-9dc0-3d6aadfea667", "text": "Hamis (4+5 < 10)", "isCorrect": true}], "timeLimit": 15}, {"id": "f2efa199-dcaf-4e7e-b48f-640817961bef", "text": "4. Ha a kör sugara 7 cm, mennyi az átmérője? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "f8aae2c3-a72e-4d5f-be08-92cc25cb7f9a", "text": "5. Hány fokos szöget zár be a szakaszfelező merőleges a szakasszal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "69f82b64-8f62-420c-9382-bf86d05a3429", "text": "6. A rombusz minden oldala egyenlő hosszú.", "type": "true-false", "options": [{"id": "68622961-d9eb-41f3-94a5-0e1ef67fad09", "text": "Igaz", "isCorrect": true}, {"id": "f6470a48-cdf0-4815-bfd7-4f6104fffe55", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "26dc86e2-a7e5-4bdf-8332-55205012ae3a", "text": "7. Milyen szög a 120°-os szög?", "type": "multiple-choice", "options": [{"id": "97ac6dea-0446-46c5-b970-dce933eeec10", "text": "Tompaszög", "isCorrect": true}, {"id": "3bba0025-3185-4774-93c1-42c2397f8543", "text": "Hegyesszög", "isCorrect": false}, {"id": "9a32a95f-360b-46b0-8949-fc629c3b2be9", "text": "Derékszög", "isCorrect": false}, {"id": "9104f926-814c-4029-a5ee-95120e865230", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}, {"id": "068e9641-c0d8-4f7f-ae51-b702bb5c5ff6", "text": "8. Hány átlója van egy négyszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "e7b99a2c-c46b-4642-96c4-689968bbb144", "text": "9. Az egybevágó alakzatok területe megegyezik.", "type": "true-false", "options": [{"id": "41bdc585-20dd-4b72-9e2d-b53d801a24ba", "text": "Igaz", "isCorrect": true}, {"id": "c53e540a-5d6e-4372-bd70-1a59d1025e50", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2b03c603-45bf-4cdb-8174-90b68ba6de71", "text": "10. Hány fokosak a szabályos háromszög szögei?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}]'::jsonb, true, NOW()),
('e747a24c-30f5-48f8-a104-4b09e9c4675f', '21feff02-016d-46e2-bb9d-c27495133b1b', '56. óra: Matematikai játékok', 'Geometriai kirakók (Tangram), alakzatok építése, stratégiák.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "6d05a47c-7424-4037-bd4d-c86cf9d55ea1", "text": "Hány darabból (tanból) áll a klasszikus Tangram kirakó játék?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "f275e5d2-670a-4851-b889-b9070196f723", "text": "Milyen síkidomokból áll a Tangram készlet?", "type": "multiple-choice", "options": [{"id": "d85e2220-cc67-4d0c-83dc-04597dd19836", "text": "5 háromszög, 1 négyzet, 1 paralelogramma", "isCorrect": true}, {"id": "a9542710-0008-40f0-9902-93f9a0cece5c", "text": "7 négyzet", "isCorrect": false}, {"id": "8f642942-86f5-4c41-badf-5856540924cb", "text": "7 kör", "isCorrect": false}, {"id": "15054346-7a95-4181-b382-46cbdfaad1e9", "text": "3 háromszög, 4 téglalap", "isCorrect": false}], "timeLimit": 15}, {"id": "33db275d-9f0d-430d-b2b7-ab450464461e", "text": "A Tangram elemeiből sokféle figura (állatok, emberi alakok, tárgyak) kirakható.", "type": "true-false", "options": [{"id": "0c374df3-d5d2-40ae-9039-bd5d2a03c569", "text": "Igaz", "isCorrect": true}, {"id": "cdce05b6-e49e-4b90-b561-e3bb56f67ebb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dffbadc1-302f-41a6-b615-fec5abfba047", "text": "A kirakós játékok fejlesztik a térszemléletet és a síkbeli alakzatok felismerését.", "type": "true-false", "options": [{"id": "78d64597-cacc-472c-9b50-bc87225a97c6", "text": "Igaz", "isCorrect": true}, {"id": "bd2e0fa3-9cfe-4f06-8281-767bf6f8c8ae", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "36127e8f-798f-4d1b-82c3-984b87726268", "text": "A szabályos sokszögekkel hégmentesen lefedhető a sík (pl. szabályos hatoszögekkel).", "type": "true-false", "options": [{"id": "197eb593-76f3-43ca-a595-651d764d71e2", "text": "Igaz", "isCorrect": true}, {"id": "0f46dbc1-34ec-4252-80a0-b061064a29f4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "41cff3df-ffab-4a13-942e-8d98a8517b4b", "text": "Hány oldala van a szabályos hexagonnak (hatszögnek)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "6dcb6cf6-c0ba-4367-b696-361e9347417f", "text": "A geometriai játékok során a próbálgatás és a logikai tervezés együtt segít a megoldásban.", "type": "true-false", "options": [{"id": "01b5e46f-e904-46f9-beef-a94ed74734ef", "text": "Igaz", "isCorrect": true}, {"id": "572aa71c-723b-4412-96f6-5dad6c912ac0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());